[URL Rewrite]
request if ${url} ~= /^https:\/\/(?:gmp|wallet)\.lakala\.com\/(?:gmp\/openapi\/v2\/resource_space\/getResourceSpace|m\/(?:a\/lama\/mgt\/activity\/biz\/query\/byMerInfo|lama\/mgt\/activity\/(?:bank|biz)\/query\/list))/i then reject_dict(200)

[MITM]
hostname = %APPEND% gmp.lakala.com, wallet.lakala.com
